  orbit: '<path d="M20.341 6.484A10 10 0 0 1 10.266 21.85"/><path d="M3.659 17.516A10 10 0 0 1 13.74 2.152"/><circle cx="12" cy="12" r="3"/><circle cx="19" cy="5" r="2"/><circle cx="5" cy="19" r="2"/>',
  // 发射塔 + 辐射弧（Lucide「radio-tower」，ISC License）：干扰分析（C/I）入口用 ——
  // 一个源朝两边打，正是「旁瓣落进别人主瓣」。与同为「辐射」族的 satellite-dish（天线波束合成）
  // 靠塔身的 Λ + 横杆区分，且分处工具栏与活动栏两条竖列，不并排比较。
  'radio-tower': '<path d="M4.9 16.1C1 12.2 1 5.8 4.9 1.9"/><path d="M7.8 4.7a6.14 6.14 0 0 0-.8 7.5"/><circle cx="12" cy="9" r="2"/><path d="M16.2 4.8c2 2 2.26 5.11.8 7.47"/><path d="M19.1 1.9a9.96 9.96 0 0 1 0 14.1"/><path d="M9.5 18h5"/><path d="m8 22 4-11 4 11"/>',
  // 「转发器频率计划」专用（非 Lucide，自绘）：方框里一个字母 F（Frequency）。
